import 'package:shared_preferences/shared_preferences.dart';
Future<void> save(String v)async{final p=await SharedPreferences.getInstance();await p.setString('{{pref_key}}',v);}
Future<String?> load()async{final p=await SharedPreferences.getInstance();return p.getString('{{pref_key}}');}
Future<void> clear()async{final p=await SharedPreferences.getInstance();await p.remove('{{pref_key}}');}
